CA,cAAA;EVmzDF;AACF;AWliEA;EACC,yBAAA;AXoiED;AWliEC;EACC,wCAAA;AXoiEF;AWhiEE;EACC,cAAA;AXkiEH;AW/hEE;EACC,8BAAA;AXiiEH;AW7hEC;EACC,sBAAA;AX+hEF;AW5hEC;;;;;;;EAOC,WAAA;AX8hEF;AW5hEC;EACC,cAAA;AX8hEF;AW1hEE;EACC,iBAAA;AX4hEH;AWxhEG;EACC,UAAA;AX0hEJ;AWrhEC;;EAEC,qBAAA;AXuhEF","file":"style.css","sourcesContent":["/*------------------------------------------------\r\n\tBase Styles\r\n-------------------------------------------------*/\r\nbody {\r\n  font-family: $font-stack;\r\n  font-weight: 400;\r\n  font-size: 16px;\r\n  line-height: 30px;\r\n  color: $text-color;\r\n}\r\n\r\na {\r\n  color: inherit;\r\n\r\n  &:hover,\r\n  &:focus {\r\n    color: $text-color;\r\n    text-decoration: none;\r\n    outline: 0 none;\r\n  }\r\n\r\n  @include transition(all 0.3s ease 0s);\r\n}\r\n\r\nh1,\r\nh2,\r\nh3,\r\nh4,\r\nh5,\r\nh6 {\r\n  color: $title-color;\r\n  font-family: $open-sans;\r\n  margin: 0;\r\n  line-height: 1.3;\r\n}\r\n\r\np {\r\n  margin-bottom: 20px;\r\n\r\n  &:last-child {\r\n    margin-bottom: 0;\r\n  }\r\n}\r\n\r\n/*\r\n * Selection color\r\n */\r\n::-moz-selection {\r\n  background-color: $primary-color;\r\n  color: $light;\r\n}\r\n\r\n::selection {\r\n  background-color: $primary-color;\r\n  color: $light;\r\n}\r\n\r\n/*\r\n *  Reset bootstrap's default style\r\n */\r\n.form-control::-webkit-input-placeholder,\r\n::-webkit-input-placeholder {\r\n  opacity: 1;\r\n  color: inherit;\r\n}\r\n\r\n.form-control:-moz-placeholder,\r\n:-moz-placeholder {\r\n  /* Firefox 18- */\r\n  opacity: 1;\r\n  color: inherit;\r\n}\r\n\r\n.form-control::-moz-placeholder,\r\n::-moz-placeholder {\r\n  /* Firefox 19+ */\r\n  opacity: 1;\r\n  color: inherit;\r\n}\r\n\r\n.form-control:-ms-input-placeholder,\r\n:-ms-input-placeholder {\r\n  opacity: 1;\r\n  color: inherit;\r\n}\r\n\r\nbutton,\r\ninput,\r\nselect,\r\ntextarea,\r\nlabel {\r\n  font-weight: 400;\r\n}\r\n\r\n.btn {\r\n  @include transition(all 0.3s ease 0s);\r\n\r\n  &:hover,\r\n  &:focus,\r\n  &:active:focus {\r\n    outline: 0 none;\r\n  }\r\n}\r\n\r\n.btn-primary {\r\n  background-color: $primary-color;\r\n  border: 0;\r\n  font-family: $open-sans;\r\n  font-weight: 700;\r\n  height: 48px;\r\n  line-height: 50px;\r\n  padding: 0 42px;\r\n  text-transform: uppercase;\r\n\r\n  &:hover,\r\n  &:focus,\r\n  &:active,\r\n  &:active:focus {\r\n    background-color: darken($primary-color, 8%);\r\n  }\r\n}\r\n\r\n.btn-border {\r\n  border: 1px solid #d7d8db;\r\n  display: inline-block;\r\n  padding: 7px;\r\n}\r\n\r\n/*\r\n *  CSS Helper Class\r\n */\r\n.clear {\r\n\r\n  &:before,\r\n  &:after {\r\n    content: \" \";\r\n    display: table;\r\n  }\r\n\r\n  &:after {\r\n    clear: both;\r\n  }\r\n}\r\n\r\n.pt-table {\r\n  display: table;\r\n  width: 100%;\r\n  @include calc(height, \"100vh - 4px\");\r\n}\r\n\r\n.pt-tablecell {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n}\r\n\r\n.overlay {\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n.relative {\r\n  position: relative;\r\n}\r\n\r\n.primary,\r\n.link:hover {\r\n  color: $primary-color;\r\n}\r\n\r\n.no-gutter {\r\n  margin-left: 0;\r\n  margin-right: 0;\r\n\r\n  &>[class^=\"col-\"] {\r\n    padding-left: 0;\r\n    padding-right: 0;\r\n  }\r\n}\r\n\r\n.flex {\r\n  @include flexbox();\r\n}\r\n\r\n.flex-middle {\r\n  @include align-items(center);\r\n}\r\n\r\n.space-between {\r\n  @include justify-content(space-between);\r\n}\r\n\r\n.nicescroll-cursors {\r\n  background: $primary-color !important;\r\n}","//\r\n// Typography\r\n//\r\n\r\n$font-stack: \"Libre Baskerville\", serif;\r\n$open-sans: \"Open Sans\", sans-serif;\r\n\r\n//\r\n// Colors\r\n//\r\n$primary-color: #fa6862;\r\n$light-dark: #1e2530;\r\n$light: #fff;\r\n$text-color: #ababab;\r\n$title-color: #1e2530;\r\n$border-color: #eee;\r\n\r\n//\r\n// Hexagon\r\n//\r\n$sqrt3: 1.7320508075688772;\r\n$edgeSize: 100px;\r\n$hexWidth: $edgeSize * 2;\r\n$hexHeight: $sqrt3 * $edgeSize;\r\n\r\n// Display\r\n$borderHover: 15px;\r\n\r\n// Easing\r\n$ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);\r\n$ease-out-quart: cubic-bezier(0.165, 0.84, 0.44, 1);\r\n","/*------------------------------------------------\n\tBase Styles\n-------------------------------------------------*/\nbody {\n  font-family: \"Libre Baskerville\", serif;\n  font-weight: 400;\n  font-size: 16px;\n  line-height: 30px;\n  color: #ababab;\n}\n\na {\n  color: inherit;\n}\na:hover, a:focus {\n  color: #ababab;\n  text-decoration: none;\n  outline: 0 none;\n}\na {\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  color: #1e2530;\n  font-family: \"Open Sans\", sans-serif;\n  margin: 0;\n  line-height: 1.3;\n}\n\np {\n  margin-bottom: 20px;\n}\np:last-child {\n  margin-bottom: 0;\n}\n\n/*\n * Selection color\n */\n::-moz-selection {\n  background-color: #fa6862;\n  color: #fff;\n}\n\n::selection {\n  background-color: #fa6862;\n  color: #fff;\n}\n\n/*\n *  Reset bootstrap's default style\n */\n.form-control::-webkit-input-placeholder,\n::-webkit-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-moz-placeholder,\n:-moz-placeholder {\n  /* Firefox 18- */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control::-moz-placeholder,\n::-moz-placeholder {\n  /* Firefox 19+ */\n  opacity: 1;\n  color: inherit;\n}\n\n.form-control:-ms-input-placeholder,\n:-ms-input-placeholder {\n  opacity: 1;\n  color: inherit;\n}\n\nbutton,\ninput,\nselect,\ntextarea,\nlabel {\n  font-weight: 400;\n}\n\n.btn {\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n}\n.btn:hover, .btn:focus, .btn:active:focus {\n  outline: 0 none;\n}\n\n.btn-primary {\n  background-color: #fa6862;\n  border: 0;\n  font-family: \"Open Sans\", sans-serif;\n  font-weight: 700;\n  height: 48px;\n  line-height: 50px;\n  padding: 0 42px;\n  text-transform: uppercase;\n}\n.btn-primary:hover, .btn-primary:focus, .btn-primary:active, .btn-primary:active:focus {\n  background-color: rgb(97.5453885258%, 25.8707334786%, 22.9251997095%);\n}\n\n.btn-border {\n  border: 1px solid #d7d8db;\n  display: inline-block;\n  padding: 7px;\n}\n\n/*\n *  CSS Helper Class\n */\n.clear:before, .clear:after {\n  content: \" \";\n  display: table;\n}\n.clear:after {\n  clear: both;\n}\n\n.pt-table {\n  display: table;\n  width: 100%;\n  height: -webkit-calc(100vh - 4px);\n  height: -moz-calc(100vh - 4px);\n  height: calc(100vh - 4px);\n}\n\n.pt-tablecell {\n  display: table-cell;\n  vertical-align: middle;\n}\n\n.overlay {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 100%;\n  height: 100%;\n}\n\n.relative {\n  position: relative;\n}\n\n.primary,\n.link:hover {\n  color: #fa6862;\n}\n\n.no-gutter {\n  margin-left: 0;\n  margin-right: 0;\n}\n.no-gutter > [class^=col-] {\n  padding-left: 0;\n  padding-right: 0;\n}\n\n.flex {\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -moz-flex;\n  display: -ms-flexbox;\n  display: flex;\n}\n\n.flex-middle {\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  align-items: center;\n}\n\n.space-between {\n  -webkit-box-pack: justify;\n  -ms-flex-pack: justify;\n  -webkit-justify-content: space-between;\n  -moz-justify-content: space-between;\n  justify-content: space-between;\n}\n\n.nicescroll-cursors {\n  background: #fa6862 !important;\n}\n\n.preloader {\n  bottom: 0;\n  left: 0;\n  position: fixed;\n  right: 0;\n  top: 0;\n  z-index: 1000;\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -moz-flex;\n  display: -ms-flexbox;\n  display: flex;\n}\n.preloader.active.hidden {\n  display: none;\n}\n\n.loading-mask {\n  background-color: #fa6862;\n  height: 100%;\n  left: 0;\n  position: absolute;\n  top: 0;\n  width: 20%;\n  -webkit-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  -moz-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  -o-transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n  transition: all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s;\n}\n.loading-mask:nth-child(2) {\n  left: 20%;\n  -webkit-transition-delay: 0.1s;\n  -moz-transition-delay: 0.1s;\n  -o-transition-delay: 0.1s;\n  transition-delay: 0.1s;\n}\n.loading-mask:nth-child(3) {\n  left: 40%;\n  -webkit-transition-delay: 0.2s;\n  -moz-transition-delay: 0.2s;\n  -o-transition-delay: 0.2s;\n  transition-delay: 0.2s;\n}\n.loading-mask:nth-child(4) {\n  left: 60%;\n  -webkit-transition-delay: 0.3s;\n  -moz-transition-delay: 0.3s;\n  -o-transition-delay: 0.3s;\n  transition-delay: 0.3s;\n}\n.loading-mask:nth-child(5) {\n  left: 80%;\n  -webkit-transition-delay: 0.4s;\n  -moz-transition-delay: 0.4s;\n  -o-transition-delay: 0.4s;\n  transition-delay: 0.4s;\n}\n\n.preloader.active.done {\n  z-index: 0;\n}\n.preloader.active .loading-mask {\n  width: 0;\n}\n\n/*------------------------------------------------\n\tStart Styling\n-------------------------------------------------*/\n.site-wrapper {\n  border-top: 4px solid #fa6862;\n}\n\n.page-close {\n  font-size: 30px;\n  position: absolute;\n  right: 30px;\n  top: 30px;\n  z-index: 100;\n}\n\n.page-title {\n  margin-bottom: 75px;\n}\n.page-title img {\n  margin-bottom: 20px;\n}\n.page-title h2 {\n  font-size: 68px;\n  margin-bottom: 25px;\n  position: relative;\n  z-index: 0;\n  font-weight: 900;\n  text-transform: uppercase;\n}\n.page-title p {\n  font-size: 16px;\n}\n.page-title .title-bg {\n  color: rgba(30, 37, 48, 0.07);\n  font-size: 158px;\n  left: 50%;\n  letter-spacing: 10px;\n  line-height: 0.7;\n  position: absolute;\n  top: 50%;\n  z-index: -1;\n  -webkit-transform: translate(-50%, -50%);\n  -moz-transform: translate(-50%, -50%);\n  -ms-transform: translate(-50%, -50%);\n  -o-transform: translate(-50%, -50%);\n  transform: translate(-50%, -50%);\n}\n\n.section-title {\n  margin-bottom: 20px;\n  overflow: hidden;\n}\n.section-title h3 {\n  display: inline-block;\n  position: relative;\n}\n.section-title h3::before, .section-title h3::after {\n  content: \"\";\n  height: 2px;\n  position: absolute;\n  bottom: 8px;\n  left: -webkit-calc(100% + 14px);\n  left: -moz-calc(100% + 14px);\n  left: calc(100% + 14px);\n}\n.section-title h3::before {\n  background-color: #1e2530;\n  width: 96px;\n  bottom: 14px;\n}\n.section-title h3::after {\n  background-color: #fa6862;\n  width: 73px;\n}\n.section-title.light h3 {\n  color: #fff;\n}\n.section-title.light h3::before {\n  background-color: #fff;\n}\n\n.page-nav {\n  bottom: 40px;\n  left: 0;\n  position: absolute;\n  right: 0;\n}\n.page-nav span {\n  font-family: \"Open Sans\", sans-serif;\n  font-size: 14px;\n  font-weight: 500;\n  line-height: 1.3;\n  text-transform: uppercase;\n}\n\n/*------------------------------------------------\n    Home Page\n-------------------------------------------------*/\n.page-home {\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  vertical-align: middle;\n}\n.page-home .overlay {\n  background-color: rgba(255, 255, 255, 0.93);\n}\n\n/* End of container */\n.hexagon-item {\n  cursor: pointer;\n  width: 200px;\n  height: 173.2050807569px;\n  float: left;\n  margin-left: -29px;\n  z-index: 0;\n  position: relative;\n  -webkit-transform: rotate(30deg);\n  -moz-transform: rotate(30deg);\n  -ms-transform: rotate(30deg);\n  -o-transform: rotate(30deg);\n  transform: rotate(30deg);\n}\n.hexagon-item:first-child {\n  margin-left: 0;\n}\n.hexagon-item:hover {\n  z-index: 1;\n}\n.hexagon-item:hover .hex-item:last-child {\n  opacity: 1;\n  -webkit-transform: scale(1.3);\n  -moz-transform: scale(1.3);\n  -ms-transform: scale(1.3);\n  -o-transform: scale(1.3);\n  transform: scale(1.3);\n}\n.hexagon-item:hover .hex-item:first-child {\n  opacity: 1;\n  -webkit-transform: scale(1.2);\n  -moz-transform: scale(1.2);\n  -ms-transform: scale(1.2);\n  -o-transform: scale(1.2);\n  transform: scale(1.2);\n}\n.hexagon-item:hover .hex-item:first-child div:before,\n.hexagon-item:hover .hex-item:first-child div:after {\n  height: 15px;\n}\n.hexagon-item:hover .hex-item div::before,\n.hexagon-item:hover .hex-item div::after {\n  background-color: #fa6862;\n}\n.hexagon-item:hover .hex-content svg {\n  -webkit-transform: scale(0.97);\n  -moz-transform: scale(0.97);\n  -ms-transform: scale(0.97);\n  -o-transform: scale(0.97);\n  transform: scale(0.97);\n}\n\n.page-home .hexagon-item:nth-child(n+5) {\n  -webkit-transform: rotate(30deg) translate(87px, -80px);\n  -moz-transform: rotate(30deg) translate(87px, -80px);\n  -ms-transform: rotate(30deg) translate(87px, -80px);\n  -o-transform: rotate(30deg) translate(87px, -80px);\n  transform: rotate(30deg) translate(87px, -80px);\n}\n\n.hex-item {\n  position: absolute;\n  top: 0;\n  left: 50px;\n  width: 100px;\n  height: 173.2050807569px;\n}\n.hex-item:first-child {\n  z-index: 0;\n  -webkit-transform: scale(0.9);\n  -moz-transform: scale(0.9);\n  -ms-transform: scale(0.9);\n  -o-transform: scale(0.9);\n  transform: scale(0.9);\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);\n}\n.hex-item:last-child {\n  transition: all 0.3s cubic-bezier(0.19, 1, 0.22, 1);\n  z-index: 1;\n}\n.hex-item div {\n  box-sizing: border-box;\n  position: absolute;\n  top: 0;\n  width: 100px;\n  height: 173.2050807569px;\n  -webkit-transform-origin: center center;\n  -moz-transform-origin: center center;\n  -ms-transform-origin: center center;\n  -o-transform-origin: center center;\n  transform-origin: center center;\n}\n.hex-item div::before, .hex-item div::after {\n  background-color: #1e2530;\n  content: \"\";\n  position: absolute;\n  width: 100%;\n  height: 3px;\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n}\n.hex-item div:before {\n  top: 0;\n}\n.hex-item div:after {\n  bottom: 0;\n}\n.hex-item div:nth-child(1) {\n  -webkit-transform: rotate(0deg);\n  -moz-transform: rotate(0deg);\n  -ms-transform: rotate(0deg);\n  -o-transform: rotate(0deg);\n  transform: rotate(0deg);\n}\n.hex-item div:nth-child(2) {\n  -webkit-transform: rotate(60deg);\n  -moz-transform: rotate(60deg);\n  -ms-transform: rotate(60deg);\n  -o-transform: rotate(60deg);\n  transform: rotate(60deg);\n}\n.hex-item div:nth-child(3) {\n  -webkit-transform: rotate(120deg);\n  -moz-transform: rotate(120deg);\n  -ms-transform: rotate(120deg);\n  -o-transform: rotate(120deg);\n  transform: rotate(120deg);\n}\n\n.hex-content {\n  color: #fff;\n  display: block;\n  height: 180px;\n  margin: 0 auto;\n  position: relative;\n  text-align: center;\n  transform: rotate(-30deg);\n  width: 156px;\n}\n.hex-content .hex-content-inner {\n  left: 50%;\n  margin: -3px 0 0 2px;\n  position: absolute;\n  top: 50%;\n  -webkit-transform: translate(-50%, -50%);\n  -moz-transform: translate(-50%, -50%);\n  -ms-transform: translate(-50%, -50%);\n  -o-transform: translate(-50%, -50%);\n  transform: translate(-50%, -50%);\n}\n.hex-content .icon {\n  display: block;\n  font-size: 36px;\n  line-height: 30px;\n  margin-bottom: 11px;\n}\n.hex-content .title {\n  display: block;\n  font-family: \"Open Sans\", sans-serif;\n  font-size: 14px;\n  letter-spacing: 1px;\n  line-height: 24px;\n  text-transform: uppercase;\n}\n.hex-content svg {\n  left: -7px;\n  position: absolute;\n  top: -13px;\n  transform: scale(0.87);\n  z-index: -1;\n  -webkit-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -moz-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  -o-transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n  transition: all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) 0s;\n}\n.hex-content:hover {\n  color: #fff;\n}\n\n/*------------------------------------------------\n    Welcome Page\n-------------------------------------------------*/\n.author-image-large {\n  position: absolute;\n  right: 0;\n  top: 0;\n}\n.author-image-large img {\n  height: -webkit-calc(100vh - 4px);\n  height: -moz-calc(100vh - 4px);\n  height: calc(100vh - 4px);\n}\n\n/*------------------------------------------------\n    About Page\n-------------------------------------------------*/\n.about-author {\n  margin-bottom: 23px;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  align-items: center;\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -moz-flex;\n  display: -ms-flexbox;\n  display: flex;\n}\n.about-author .author-thumb {\n  background-color: #fff;\n  border: 5px solid #1e2530;\n  margin-right: 30px;\n  padding: 5px;\n}\n.about-author .author-thumb img {\n  border: 2px solid #1e2530;\n  width: 145px;\n}\n.about-author .author-desc p {\n  color: #1e2530;\n  font-family: \"Open Sans\", sans-serif;\n  letter-spacing: 1px;\n  margin-bottom: 4px;\n  text-transform: uppercase;\n}\n.about-author .author-desc b {\n  font-family: \"Open Sans\", sans-serif;\n}\n\n/*------------------------------------------------\n    Games Page\n-------------------------------------------------*/\n.page-games .page-title {\n  margin-bottom: 22px;\n}\n\n.games-view {\n  display: inline-block;\n  list-style: none;\n  margin: 0 0 12px;\n  padding: 0;\n}\n.games-view li {\n  display: inline-block;\n  margin: 0 12px;\n}\n.games-view a {\n  border-bottom: 2px solid transparent;\n  display: inline-block;\n  font-family: \"Open Sans\", sans-serif;\n  font-size: 14px;\n  letter-spacing: 1px;\n  padding-bottom: 2px;\n  text-transform: uppercase;\n}\n.games-view .active {\n  border-bottom-color: #fa6862;\n  color: #fa68