;\n}\n\n.switcher-body h4 {\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n\n.switcher-body select {\n  border: 1px solid #e5e5e5;\n  height: 40px;\n  margin-bottom: 20px;\n  width: 100%;\n  -webklit--appearance: none;\n  -moz-appearance: none;\n  appearance: none;\n}\n\n.color-options {\n  margin-bottom: 10px;\n  padding: 0;\n}\n\n.color-options li {\n  display: inline-block;\n  background-color: #e6ae03;\n  height: 30px;\n  margin-bottom: 10px;\n  margin-right: 6px;\n  text-indent: -9999em;\n  width: 30px;\n  cursor: pointer;\n}\n\n.color-options li.c0 {\n  background-color: #fa6862;\n}\n\n.color-options li.c1 {\n  background-color: #02b7ce;\n}\n\n.color-options li.c2 {\n  background-color: #86a438;\n}\n\n.color-options li.c3 {\n  background-color: #f3a36d;\n}\n\n.pattern-options li {\n  font-family: \"Roboto\", sans-serif;\n  border: 1px solid #cccccc;\n  cursor: pointer;\n  float: left;\n  height: 40px;\n  margin: 0 10px 10px 0;\n  text-transform: capitalize;\n  width: 50px;\n}\n\n.pattern-options li:last-child {\n  border: 0 none;\n  height: auto;\n  padding-top: 8px;\n  width: auto;\n}\n\n.pattern-options li img {\n  width: 100%;\n  height: 100%;\n}\n\n/*------------------------------------------------\n\tResponsive Media Queries\n-------------------------------------------------*/\n/*============================================================\n\tMacbook pro 13 inch\n==============================================================*/\n/*============================================================\n\tFor Small Desktop / tablet landscape\n==============================================================*/\n@media (min-width: 980px) and (max-width: 1150px) {\n  .author-image-large img {\n    height: -webkit-calc(80vh - 4px);\n    height: -moz-calc(80vh - 4px);\n    height: calc(80vh - 4px);\n  }\n}\n/*============================================================\n\tTablet (Portrait) Design for a width of 768px\n=========================================================